from z3 import *

def main():
    n = 2

    categories = {
        "name": ["Eric", "Arnold"],
        "music": ["rock", "pop"],
        "style": ["colonial", "victorian"],
        "lunch": ["grilled cheese", "pizza"],
        "sport": ["basketball", "soccer"],
        "child": ["Bella", "Fred"],
    }

    solver = Solver()
    house_of = {}

    for cat, values in categories.items():
        cat_vars = []
        for value in values:
            var_name = f"{cat}_{value}".replace(" ", "_")
            var = Int(var_name)
            house_of[(cat, value)] = var
            solver.add(var >= 1, var <= n)
            cat_vars.append(var)
        solver.add(Distinct(cat_vars))

    solver.add(house_of[("style", "colonial")] == house_of[("lunch", "pizza")])
    solver.add(house_of[("name", "Arnold")] == house_of[("style", "colonial")])
    solver.add(house_of[("music", "pop")] == house_of[("style", "colonial")])
    solver.add(house_of[("lunch", "pizza")] != 2)
    solver.add(house_of[("name", "Eric")] == house_of[("sport", "soccer")])
    solver.add(house_of[("lunch", "grilled cheese")] == house_of[("child", "Bella")])

    if solver.check() != sat:
        return

    model = solver.model()

    def get_attribute(cat, house):
        for value in categories[cat]:
            if model.evaluate(house_of[(cat, value)]).as_long() == house:
                return value
        return "unknown"

    order = ["name", "music", "style", "lunch", "sport", "child"]

    for house in range(1, n + 1):
        attrs = [get_attribute(cat, house) for cat in order]
        print(f"House {house}: " + ", ".join(attrs))

if __name__ == "__main__":
    main()

def parse_time(t):
    h, m = map(int, t.split(":"))
    return h * 60 + m

def format_time(t):
    return f"{t // 60:02d}:{t % 60:02d}"

day = "Monday"
work_start = parse_time("09:00")
work_end = parse_time("17:00")
duration_minutes = 30

busy_intervals = {
    "Deborah": [],
    "Albert": [
        (parse_time("09:00"), parse_time("10:00")),
        (parse_time("10:30"), parse_time("12:00")),
        (parse_time("15:00"), parse_time("16:30")),
    ],
}

latest_end = {
    "Albert": parse_time("11:00"),
}

def overlaps(start, end, busy_start, busy_end):
    return start < busy_end and end > busy_start

answer = None
for start in range(work_start, work_end - duration_minutes + 1):
    end = start + duration_minutes
    valid = True

    for participant in busy_intervals:
        if latest_end.get(participant, work_end) < end:
            valid = False
            break

        for busy_start, busy_end in busy_intervals[participant]:
            if overlaps(start, end, busy_start, busy_end):
                valid = False
                break

        if not valid:
            break

    if valid:
        answer = [day, format_time(start), format_time(end)]
        break

print(answer)
